import{_ as t,C as e,o as p,c as l,j as i,a as n,G as h,aj as o}from"./chunks/framework.BZR1KcQy.js";const d="/wiki/img/1c/image.png",c="/wiki/img/1c/image-1.png",k="/wiki/img/1c/image-2.png",r="/wiki/img/1c/image-3.png",g="/wiki/img/1c/image-4.png",F="/wiki/img/1c/image-5.png",u="/wiki/img/1c/image-6.png",b="/wiki/img/1c/image-7.png",C="/wiki/img/1c/image-9.png",v="/wiki/img/1c/image-10.png",P=JSON.parse('{"title":"1С Предприятие 8.3","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/wi/1c.md","filePath":"docs/wi/1c.md","lastUpdated":1788533046000}'),y={name:"docs/wi/1c.md"};function m(B,s,E,_,x,q){const a=e("ImageZoom");return p(),l("div",null,[s[0]||(s[0]=i("h1",{id:"_1с-предприятие-8-3",tabindex:"-1"},[n("1С Предприятие 8.3 "),i("a",{class:"header-anchor",href:"#_1с-предприятие-8-3","aria-label":'Permalink to "1С Предприятие 8.3"'},"​")],-1)),h(a,{src:"https://v8.1c.ru/upload/static/social-media-logo.png"}),s[1]||(s[1]=o(`<p>1С:Предприятие — это универсальная платформа для автоматизации бизнес-процессов и управления данными, широко используемая в странах СНГ. Она объединяет в себе мощный технологический фреймворк для разработки и обширную экосистему готовых отраслевых и функциональных решений (конфигураций), таких как бухгалтерский учёт, управление торговлей, зарплата и кадры, CRM и ERP. Система позволяет не только вести учёт и формировать регламентированную отчётность, но и эффективно управлять операционной деятельностью компании благодаря гибкости настройки, механизмам сложных расчетов, интеграционным возможностям и поддержке работы как в локальных, так и в облачных инфраструктурах.</p><h2 id="получение-бесплатнои-лицензии-для-разработчиков" tabindex="-1">Получение бесплатной лицензии для разработчиков <a class="header-anchor" href="#получение-бесплатнои-лицензии-для-разработчиков" aria-label="Permalink to &quot;Получение бесплатной лицензии для разработчиков&quot;">​</a></h2><p>Зарегистрируйтесь на сайте <a href="https://developer.1c.ru/" target="_blank" rel="noreferrer">1С Для Разработчиков</a></p><h3 id="основные-моменты" tabindex="-1">Основные моменты <a class="header-anchor" href="#основные-моменты" aria-label="Permalink to &quot;Основные моменты&quot;">​</a></h3><h4 id="для-каких-целеи-можно-использовать-комьюнити-лицензию" tabindex="-1">Для каких целей можно использовать комьюнити-лицензию? <a class="header-anchor" href="#для-каких-целеи-можно-использовать-комьюнити-лицензию" aria-label="Permalink to &quot;Для каких целей можно использовать комьюнити-лицензию?&quot;">​</a></h4><p>Исключительно для разработки и отладки прикладных решений (конфигураций) на базе технологической платформы 1С:Предприятие. Использовать комьюнити-лицензию для решения реальных управленческих и учетных задач нельзя. (Строго говоря: Комьюнити-лицензия не дает право эксплуатации технологической платформы 1С:Предприятие и прикладных решений, работающих на базе технологической платформы 1С:Предприятие, по их прямому назначению, т.е. для решения реальных управленческих и учетных задач на предприятиях и в учреждениях, независимо от организационно-правовой формы, в т.ч. у индивидуальных предпринимателей и самозанятых).</p><h4 id="на-каком-количестве-компьютеров-можно-активировать-комьюнити-лицензию" tabindex="-1">На каком количестве компьютеров можно активировать комьюнити-лицензию? <a class="header-anchor" href="#на-каком-количестве-компьютеров-можно-активировать-комьюнити-лицензию" aria-label="Permalink to &quot;На каком количестве компьютеров можно активировать комьюнити-лицензию?&quot;">​</a></h4><p>Комьюнити-лицензию можно активировать только на одном компьютере. При необходимости использования комьюнити-лицензии на нескольких компьютерах – нужно активировать отдельные экземпляры лицензии. Всего можно активировать не более трех экземпляров. Деактивировать ненужные лицензии можно в личном кабинете на портале <code>developer.1c.ru</code>.</p><h4 id="какие-есть-ограничения-при-использовании-комьюнити-лицензии" tabindex="-1">Какие есть ограничения при использовании комьюнити-лицензии? <a class="header-anchor" href="#какие-есть-ограничения-при-использовании-комьюнити-лицензии" aria-label="Permalink to &quot;Какие есть ограничения при использовании комьюнити-лицензии?&quot;">​</a></h4><p>Комьюнити-лицензию можно использовать исключительно для разработки и отладки решений на базе платформы 1С:Предприятие.</p><p>Использование комьюнити-лицензии сопровождается информационными сообщениями «Версия для разработчиков» в интерфейсе технологической платформы 1С:Предприятие.</p><p>Комьюнити-лицензия разрешает:</p><ul><li>Обеспечивать совместную работу в одной информационной базе для следующих сеансов (лицензии раздаются сервером 1С:Предприятие) <ul><li>Не более 3 сеансов с прямым подключением</li><li>Не более 1 сеанса при подключении через веб-сервер</li><li>Не более 1 сеанса клиента системы «1С:Аналитика»</li><li>Не более 1 сеанса мобильного клиента</li></ul></li><li>Допускается использование не более 2 разных лицензий для разработчиков в одной информационной базе</li></ul><p>Допускается также подключение единственного сеанса с комьюнити-лицензией к серверу 1С:Предприятия для целей отладки и внесения доработок. В остальных случаях использование клиентских лицензий и лицензий на сервер 1С:Предприятие совместно с комьюнити-лицензией не допускается.</p><h2 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to &quot;Установка&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">ВНИМАНИЕ</p><p>На данный момент отсутствует совместимость 1С:Предприятие 8.3 с П11, поэтому все действия выполняются на 10 Платформе. Вроде как, я не тестировал, работоспособна версия 8.5.</p><p>В репозитории c10f2 есть пакеты <code>postgresql16-1C-*</code> (возможно, это из-за ФСТЭК и сертификации PostgreSQL), но в П10 есть только <code>postgresql15-1C-*</code>, а в П11 есть <code>postgresql17-1C-*</code>. Вот такой вот бардак на данный момент.</p></div><h3 id="шаг-1-получение-архива" tabindex="-1">Шаг 1. Получение архива <a class="header-anchor" href="#шаг-1-получение-архива" aria-label="Permalink to &quot;Шаг 1. Получение архива&quot;">​</a></h3><p>На сайте <a href="https://developer.1c.ru/" target="_blank" rel="noreferrer">1С Для Разработчиков</a> перейдите в раздел: Продукты - 1С:Предприятие - Комьюнити-лицензии - Скачать (Linux)</p><p>На момент написания данной статьи необходимо выбрать версию: <code>8.3.27.1688</code></p><h3 id="шаг-2-обновление-системы-до-актуального-состояния" tabindex="-1">Шаг 2. Обновление системы до актуального состояния <a class="header-anchor" href="#шаг-2-обновление-системы-до-актуального-состояния" aria-label="Permalink to &quot;Шаг 2. Обновление системы до актуального состояния&quot;">​</a></h3><p>Установка любой программы выполняется на чистой системе только после обновления системы и ядра до актуального состояния:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> su</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-upgrade</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">update-kernel</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reboot</span></span></code></pre></div><h3 id="шаг-3-установка-1с-предприятие" tabindex="-1">Шаг 3. Установка 1С:Предприятие <a class="header-anchor" href="#шаг-3-установка-1с-предприятие" aria-label="Permalink to &quot;Шаг 3. Установка 1С:Предприятие&quot;">​</a></h3><p>Уточните актуальную версию PostgreSQL для 1С:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-cache</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> search</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1C</span></span></code></pre></div><p>Актуальная версия на момент написания статьи - 15.</p><p>Необходимо настроить <code>postgresql15-1C-server</code>, для этого необходимо установить пакеты:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql15-1C-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql15-1C-contrib</span></span></code></pre></div><p>После установки инициализируем базу:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/etc/init.d/postgresql</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> initdb</span></span></code></pre></div><p>Необходимо заменить конфигурационные файлы:</p><ul><li>В <code>/var/lib/pgsql/data/postgresql.conf</code> заменить строку:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#listen_addresses = &#39;localhost&#39;</span></span></code></pre></div><p>на</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listen_addresses</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;*&#39;</span></span></code></pre></div><ul><li>В <code>/var/lib/pgsql/data/pg_hba.conf</code> добавить строку:</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    all</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    all</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ip-адрес</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> сервер</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">а</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/21</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    trust</span></span></code></pre></div><p>Запускаем сервис PostgreSQL и включим его в автозагрузку:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgresql</span></span></code></pre></div><p>Устанавливаем пакет <code>1c-preinstall-full</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1c-preinstall-full</span></span></code></pre></div><p>Установим драйвер аппаратных ключей защиты и менеджеров лицензий, включим работу сервиса и добавим в автозагрузку:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> haspd</span></span></code></pre></div><p>Запускаем процесс <code>haspd</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --now</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> haspd</span></span></code></pre></div><p>Добавим <code>ip-адрес</code> и <code>hostname</code> текущей машины в <code>/etc/hosts</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)    $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hostname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">)&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/hosts</span></span></code></pre></div><p>Устанавливаем 1С клиент и сервер:</p><p>Распаковываем архив дистрибутива 1С, скачанный ранее.</p><p>Запустить установку 1С:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./setup*.run</span></span></code></pre></div><p>В программе установки, выбираем русский язык и все необходимые компоненты, необходимые для установки.</p><p>Настроить запуск сервера 1С сервисом:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> link</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/1cv8/x86_64/8.3.27.1688/srv1cv8-8.3.27.1688@.service</span></span></code></pre></div><p>Включить автоматический запуск сервера 1С:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> srv1cv8-8.3.27.1688@</span></span></code></pre></div><p>Запустить сервер 1C с помощью сервиса:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> srv1cv8-8.3.27.1688@default.service</span></span></code></pre></div><p>Проверяем состояние портов, порты должны прослушиваться:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">netstat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tnlp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ragent|rmngr|rphost&quot;</span></span></code></pre></div><p>Создаем пользователю <code>postgres</code> пароль <code>333</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">psql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;ALTER USER postgres PASSWORD &#39;333&#39;&quot;</span></span></code></pre></div><p>Установка завершена!</p><h2 id="создание-новои-информационнои-базы-на-сервере-1с-предприятие" tabindex="-1">Создание новой информационной базы (НА СЕРВЕРЕ 1С ПРЕДПРИЯТИЕ) <a class="header-anchor" href="#создание-новои-информационнои-базы-на-сервере-1с-предприятие" aria-label="Permalink to &quot;Создание новой информационной базы (НА СЕРВЕРЕ 1С ПРЕДПРИЯТИЕ)&quot;">​</a></h2><p>Настройка параметров подключения Далее указать (на примере базы уровня 1 категории нет):</p><ol><li>Кластер серверов – данном случае будет localhost:1541;</li><li>Имя информационной базы – например, ib10;</li><li>Защищенное соединение – указать «Установка соединения»;</li><li>тип СУБД – PostgreSQL;</li><li>сервер баз данных – localhost (для данного примере, как порт 5432 по умолчанию не меняли) – если сервер баз данных выделеннный, то указать IP-адрес сервера баз данных;</li><li>имя базы данных – например, db10;</li><li>пользователь базы данных – pgsql10 (в нашем примере этот пользователь имеет метку 1:0:0);</li><li>пароль пользователя – пароль роли pgsql10 (см. пункт 4.2.7);</li><li>флаг «Создать базу данных в случае отсутствия» – не снимать;</li><li>взвести флаг «Установить блокировку регламентных заданий».</li></ol><h2 id="ошибки" tabindex="-1">Ошибки <a class="header-anchor" href="#ошибки" aria-label="Permalink to &quot;Ошибки&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Нехватка памяти</p><p>При запуске клиента 1С он вылетает и выдаёт ошибку:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LLVM ERROR: out of memory</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Buffer allocation failed</span></span></code></pre></div><p>Для решения отредактируйте файл <code>~/.bash_profile</code> и добавьте в конце следующую строчку:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WEBKIT_DISABLE_DMABUF_RENDERER</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div></div><h2 id="подготовка-к-активации-первои-программнои-лицензии" tabindex="-1">Подготовка к активации первой программной лицензии <a class="header-anchor" href="#подготовка-к-активации-первои-программнои-лицензии" aria-label="Permalink to &quot;Подготовка к активации первой программной лицензии&quot;">​</a></h2><p>Создать пустую информационную базу. Пуск – Офис – 1C:Enterprise 64(8.3.24.1762) – Добавить информационную базу. Открыть информационную базу в режиме Конфигуратор. Поскольку программная лицензия не активирована, то будет выдано сообщение об отсутствии лицензии</p><p><img src="`+d+'" alt="alt text"></p><p>Выбрать меню «Получить лицензию»</p><p>Откроется диалог «Регистрация комплекта». Ввести регистрационный номер основной поставки, указанный на желтом бланке лицензионного соглашения, а также, указанный в разделах 7 и 8 формуляра средства. Далее:</p><ol><li>Вскрыть конверт с пин-кодами активации и ввести первый из пин-кодов.</li><li>Нажать на пункт меню «Дополнительно» и выполнить действия:</li><li>Взвести флаг «Установка на сервер»;</li><li>Снять флаг «Автоматическое получение»</li><li>Наименование сервера указать как localhost;</li><li>Номер порта по умолчанию 1540 исправить на 8000;</li><li>Нажать на кнопку «Далее»</li></ol><p><img src="'+c+'" alt="alt text"></p><p>Нажать на кнопку «Далее».</p><p>– откроется диалог «Операции с лицензией» (рис.5).</p><p><img src="'+k+'" alt="alt text"></p><p>Выбрать меню «Первый запуск».</p><p><img src="'+r+'" alt="alt text"></p><p>Выбираем сохранить данные</p><p><img src="'+g+'" alt="alt text"></p><p>После чего нажимаем далее</p><p><img src="'+F+'" alt="alt text"></p><p>После чего нажимаем далее</p><p><img src="'+u+'" alt="alt text"></p><p>На электронном носителе</p><p><img src="'+b+'" alt="alt text"></p><p>Появится диалог регистрации лицензии (рис 12). Следует нажать на кнопку «Сохранить». Будет сформирован файл запроса лицензии вида «txNNNNNN.txt» (рис.13).</p><p><img src="'+C+'" alt="alt text"></p><p>Сохранить файл в выбранном каталоге.</p><h2 id="проболема-с-компьюнити-лицензиеи" tabindex="-1">ПРОБОЛЕМА С компьюнити лицензией <a class="header-anchor" href="#проболема-с-компьюнити-лицензиеи" aria-label="Permalink to &quot;ПРОБОЛЕМА С компьюнити лицензией&quot;">​</a></h2><p>Проблема: при настройке тестового стенда 1C на community лицензии (далее CL) попадаем на то, что активация лицензии проходит корректно, но клиент 1С не запускается</p><p><img src="'+v+'" alt="alt text"></p><p>По &quot;Подробно...&quot; информации недостаточно:</p><p>На сервере 1С:Предприятия не найдена лицензия. Не обнаружен ключ защиты программы или полученная программная лицензия! по причине: Файл программной лицензии не найден локальный ключ недоступен: Status=-100, EN8SA Локальный, не установлен Поиск лицензии в сервисе лицензирования: Файл программной лицензии не найден</p><p>Решение: цепляемся за фразу &quot;Файл программной лицензии не найден&quot; - скорее всего, где-то не хватает каких-то прав. Путем длительных медитаций и гугления понимаем причину: активация CL происходит из клиента 1С. Клиент запускается от текущего пользователя. И от текущего пользователя же активируется CL. Что это значит физически - файл lic будет создан в домашнем каталоге пользователя, а конкретнее здесь (у меня пользователь unich):</p><p>Путь файла /home/unich/.1cv8/1C/1cv8/conf/20250309061857.lic права у пользователя unich в группе unich. А сервер 1С работает от пользователя и группы usr1cv8:grp1cv8 (по-умолчанию), и этот пользователь таким образом файл не видит. Что с этим делать? Сначала переместить файл туда, где его ожидает увидеть платформа. Где живут файлы программной лицензии в linux смотрим на ИТС: Расположение файлов с программными лицензиями .. Для ОС Linux. В этом списке я пробовал каталог пользователя usr1cv8, каталог var/1c/licenses - не помогло. Скорее всего у меня руки кривые, и проблема в настройке прав, но взлетело перемещение в глобальный каталог конфигурационных файлов:</p><p>sudo mv ~/.1cv8/1C/1cv8/conf/20250309061857.lic /opt/1cv8/conf/</p><p>Сразу после этого нужно изменить владельца и группу файла:</p><p>sudo chown usr1cv8:grp1cv8 /opt/1cv8/conf/20250309061857.lic</p><p><a href="https://vkvideo.ru/video-198342647_456239144" target="_blank" rel="noreferrer">https://vkvideo.ru/video-198342647_456239144</a></p><p>А если даже это не помогает. То перед получением лицензий.</p><ol><li>Удалите все лицензии во всех папках в которых найдете (я даже корзину чистил)</li><li>Удалите файл: 1cv8conn.pfl в каталоге пользователя</li><li>Получите лицензию.</li><li>Перенесите в общий каталог. И дайте полный доступ всем пользователям.</li></ol>',104))])}const A=t(y,[["render",m]]);export{P as __pageData,A as default};
